ns.Data.RaceNotes = {
  text = "Forever Rogue races: Human, Dwarf, Gnome, Night Elf and High Order Skyborne (Alliance); Orc, Troll, Undead and Windshaper Skyborne (Horde) - every race except Tauren. Icy Veins (Nov 18): for Assassination and Combat, Undead (Touch of the Grave) is the best Horde race (Troll only wins against Beasts) and Gnome (Eureka!, Escape Artist) the best Alliance race. Subtlety: racial differences are very minor; Orc (Blood Fury) and Undead (slim edge) for Horde; Dwarf (+1% hit, Stoneform), Night Elf (burst racial, harder to detect) and Gnome (Escape Artist, Eureka!, +5% max Energy) for Alliance. Human Ruthless (+1% crit, no sword needed) is the Alliance Combat pick per wowfdb. Skyborne need the Skyborne Heroic Pack and start on Zephras Isle; Icy Veins says they get no level-10 class quest. Rip is a Human Rogue (Alliance): Ruthless crit; level-10 quest Seek out SI:7.",
  also_sources = { "https://www.icy-veins.com/wow-forever/assassination-rogue-melee-dps-pve-guide", "https://www.icy-veins.com/wow-forever/subtlety-rogue-melee-dps-pve-guide", "https://foreverguide.net/classes/rogue/", "https://wowfdb.com/classes/rogue/", "https://endgametools.com/en/wow-forever/spells/rogue" },
  source_url = "https://www.icy-veins.com/wow-forever/combat-rogue-melee-dps-pve-guide",
  checked = "2026-11-19",
}

